using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Diagnostics;using System.Windows;using System.Windows.Media;using System.Windows.Threading;using RingTimer;
class CardPerformance {
 [STAThread]static int Main(string[] args){Native.SetProcessDPIAware();var app=new Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};MenuWindow menu=null;Bubble bubble=null;var settings=new AppearanceSettings(null);try{
 Theme.Apply(true,null,null,null);var engine=new TimerEngine(new TimerState(),()=>DateTime.UtcNow);menu=new MenuWindow(new FeatureRegistry(new TimerFeature(engine,()=>{}),new StatsFeature(new StatsStore(null)),new ContextFeature()),()=>{},()=>{},settings){Left=70,Top=50,AnimationsEnabled=false};menu.OpenFeature("timer");menu.Reveal();Pump(500);double dpi=Native.ScaleFor(menu.Handle);Theme.Snapshot(menu,Path.Combine(args[0],args[1]+"-flat.png"),dpi);
 bubble=new Bubble();bubble.Show();var dock=typeof(Theme).GetField("LauncherDockInset");double inset=dock==null?14:(int)dock.GetRawConstantValue();var bounds=menu.PixelBounds;var b=bubble.PixelBounds;bubble.MovePixels(bounds.Right-(int)(inset*dpi)-b.Width,bounds.Bottom-(int)(inset*dpi)-b.Height);bubble.SetContext(new ContextUsage{Known=true,Used=61000,Capacity=100000});menu.AnchorBounds=()=>bubble.PixelBounds;var launcher=typeof(MenuWindow).GetProperty("Launcher",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic);if(launcher!=null)launcher.SetValue(menu,bubble,null);Pump(100);
 var card=menu.CardPresenter;card.Begin(new Point(180,250));Pump(200);Theme.Snapshot(menu,Path.Combine(args[0],args[1]+"-zero.png"),dpi);
 var clock=Stopwatch.StartNew();var intervals=new List<double>();double last=-1;long frames=0;var process=Process.GetCurrentProcess();TimeSpan cpu=process.TotalProcessorTime;long memory=process.PrivateMemorySize64;var frame=new DispatcherFrame();
 EventHandler render=(s,e)=>{double t=clock.Elapsed.TotalSeconds;card.Move(new Point(180+160*Math.Sin(t*2.4),250+220*Math.Cos(t*1.8)));if(t>=1){if(last>=0)intervals.Add((t-last)*1000);last=t;frames++;}if(t>=6)frame.Continue=false;};CompositionTarget.Rendering+=render;
 var limit=new DispatcherTimer{Interval=TimeSpan.FromSeconds(9)};limit.Tick+=(s,e)=>frame.Continue=false;limit.Start();try{Dispatcher.PushFrame(frame);}finally{CompositionTarget.Rendering-=render;limit.Stop();}
 process.Refresh();intervals.Sort();double seconds=clock.Elapsed.TotalSeconds;string report="label="+args[1]+" tier="+(RenderCapability.Tier>>16)+" dpi="+dpi+" frames="+frames+" callbacks_per_second="+(frames/Math.Max(1,seconds-1)).ToString("F1")+" median_ms="+(intervals.Count==0?0:intervals[intervals.Count/2]).ToString("F2")+" p95_ms="+(intervals.Count==0?0:intervals[(int)((intervals.Count-1)*.95)]).ToString("F2")+" cpu_one_core_percent="+((process.TotalProcessorTime-cpu).TotalSeconds/seconds*100).ToString("F1")+" private_mb="+(process.PrivateMemorySize64/1048576.0).ToString("F1")+" delta_mb="+((process.PrivateMemorySize64-memory)/1048576.0).ToString("F1");File.WriteAllText(Path.Combine(args[0],args[1]+".txt"),report);Console.WriteLine(report);card.Release();Pump(100);return 0;
 }catch(Exception e){Console.WriteLine(e);return 1;}finally{if(menu!=null){menu.Disposing=true;menu.Close();}if(bubble!=null)bubble.Close();settings.Dispose();app.Shutdown();}}
 static void Pump(int ms){var frame=new DispatcherFrame();var timer=new DispatcherTimer{Interval=TimeSpan.FromMilliseconds(ms)};timer.Tick+=(s,e)=>{timer.Stop();frame.Continue=false;};timer.Start();Dispatcher.PushFrame(frame);}
}
